// 1. 獲取所有數據
const allSubjects = $('Database_Subjects').all().map(i => i.json);
const allLenses = $('Database_Lenses').all().map(i => i.json);
const history = $('Generator_Output').all().map(i => i.json);

// 2. 建立歷史記錄的 "指紋庫" (用於去重)
// 格式: "Subject_Lens" (轉小寫以避免大小寫誤差)
const historySet = new Set();
history.forEach(item => {
  if (item.Subject && item.Lens) {
    historySet.add(`${item.Subject.trim().toLowerCase()}_${item.Lens.trim().toLowerCase()}`);
  }
});

// 3. 設置目標生成數量
const TARGET_COUNT = 100;
let results = [];

// 4. 優先級選題邏輯 (Round-Robin with Priority)
// 我們不隨機選 Subject，而是從頭(流行度高)遍歷到尾。
// 為確保多樣性，我們每一輪只給每個 Subject 分配 1 個 Lens，直到湊滿 50 個。

let subjectsLoopCount = 0; // 防止死循環
while (results.length < TARGET_COUNT && subjectsLoopCount < 5) { // 最多遍歷整個Subject列表5次

  for (let i = 0; i < allSubjects.length; i++) {
    if (results.length >= TARGET_COUNT) break;

    const subjectObj = allSubjects[i];
    const subjectName = subjectObj.Subject;

    // 嘗試為這個 Subject 找一個可用的 Lens
    // 為了多樣性，我們 "隨機" 嘗試 Lens，直到找到一個沒用過的
    // (如果 Lens 列表很大，隨機嘗試效率很高)

    let attempts = 0;
    let foundLens = null;

    // 創建一個 Lens 的隨機索引數組，避免重複嘗試同一個 Lens
    let lensIndices = Array.from({length: allLenses.length}, (_, k) => k);
    // Fisher-Yates Shuffle 隨機打亂 Lens 順序
    for (let k = lensIndices.length - 1; k > 0; k--) {
        const j = Math.floor(Math.random() * (k + 1));
        [lensIndices[k], lensIndices[j]] = [lensIndices[j], lensIndices[k]];
    }

    // 遍歷打亂後的 Lens 列表
    for (let idx of lensIndices) {
      const lensObj = allLenses[idx];
      const lensName = lensObj.Lens;
      const uniqueKey = `${subjectName.trim().toLowerCase()}_${lensName.trim().toLowerCase()}`;

      // 檢查是否在歷史庫中
      if (!historySet.has(uniqueKey)) {
        // 檢查是否在 "本次已選" 列表中 (防止本次重複)
        const isCurrentlySelected = results.some(r => 
          r.json.subject === subjectName && r.json.lens === lensName
        );

        if (!isCurrentlySelected) {
          foundLens = lensObj;
          break; // 找到一個就停，換下一個 Subject
        }
      }
    }

    if (foundLens) {
      results.push({
        json: {
          subject: subjectObj.Subject,
          category: subjectObj.Category,
          traits: subjectObj.Traits,
          lens: foundLens.Lens,
          focus: foundLens.Focus
        }
      });
    }
  }
  subjectsLoopCount++;
}

const cleanList = results.map(item => item.json);

// 2. 返回一個單獨的 Item，裡面包含整個列表
return [
  {
    json: {
      // 這就是你要的大 JSON 字符串，方便 AI 讀取
      // 你也可以不 stringify，直接傳數組，但 stringify 對 Token 控制更精確
      all_candidates_json: cleanList,

      // 這是原始數組格式，如果你後續還想用 Code 處理
      all_candidates_array: cleanList
    }
  }
];

